DROP TABLE IF EXISTS `t_course_ware`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_course_ware`
(
    `id`                     int NOT NULL AUTO_INCREMENT,
    `name`                   varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
    `create_user`            int                                                           DEFAULT NULL,
    `create_time`            datetime                                                      DEFAULT NULL,
    `deleted`                bit(1)                                                        DEFAULT NULL,
    `file_type`              int                                                           DEFAULT NULL COMMENT '璇句欢绫诲瀷锛?.瑙嗛   2.鏂囨。',
    `original_path`          varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '鍘熷鏂囨。',
    `file_name`              varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
    `description`            varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '鎻忚堪',
    `preview_path`           varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '棰勮鏂囦欢',
    `create_department_id`   int                                                           DEFAULT NULL,
    `course_ware_archive_id` int                                                           DEFAULT NULL,
    `max_length`             int                                                           DEFAULT NULL COMMENT '璇句欢鏃堕暱',
    `vm_type`                varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '铏氭嫙鏈虹幆澧?,
    PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=57 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC;
