DROP TABLE IF EXISTS `t_credential_template`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_credential_template`
(
    `id`                   int NOT NULL AUTO_INCREMENT,
    `name`                 varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '妯℃澘鍚嶇О',
    `company`              varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
    `template_image_path`  varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '妯℃澘鍥剧墖鍦板潃',
    `create_user`          int                                                           DEFAULT NULL,
    `create_time`          datetime                                                      DEFAULT NULL,
    `deleted`              bit(1)                                                        DEFAULT NULL,
    `create_department_id` int                                                           DEFAULT NULL,
    `configuration`        json                                                          DEFAULT NULL,
    PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;
/*!40101 SET character_set_client = @saved_cs_client */;

