DROP TABLE IF EXISTS `t_exam_paper_answer_monitor`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_exam_paper_answer_monitor`
(
    `id`                    bigint NOT NULL AUTO_INCREMENT,
    `exam_paper_id`         bigint                                                        DEFAULT NULL COMMENT '璇曞嵎Id',
    `paper_name`            varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '璇曞嵎鍚嶇О',
    `paper_type`            int                                                           DEFAULT NULL COMMENT '璇曞嵎绫诲瀷(浜哄伐缁勫嵎銆佹娊棰樼粍鍗枫€侀殢鏈虹粍鍗?',
    `system_score`          int                                                           DEFAULT NULL COMMENT '绯荤粺鍒ゅ垎',
    `user_score`            int                                                           DEFAULT NULL COMMENT '鐢ㄦ埛寰楀垎',
    `paper_score`           int                                                           DEFAULT NULL COMMENT '璇曞嵎鎬诲垎',
    `question_correct`      int                                                           DEFAULT NULL COMMENT '姝ｇ‘棰樻暟',
    `question_count`        int                                                           DEFAULT NULL COMMENT '棰樼洰鎬绘暟',
    `cheat_count`           int                                                           DEFAULT NULL,
    `do_time`               int                                                           DEFAULT NULL COMMENT '鑰楁椂',
    `create_user`           int                                                           DEFAULT NULL COMMENT '鍒涘缓浜?,
    `create_time`           datetime                                                      DEFAULT NULL COMMENT '鍒涘缓鏃堕棿',
    `update_time`           datetime                                                      DEFAULT NULL,
    `exam_paper_archive_id` int                                                           DEFAULT NULL COMMENT '璇曞嵎鍒嗙被Id',
    `exam_paper_build_id`   bigint                                                        DEFAULT NULL COMMENT '璇曞嵎鏋勫缓Id',
    `create_department_id`  int                                                           DEFAULT NULL,
    `answer_frame_content`  json                                                          DEFAULT NULL,
    `exam_paper_child_id`   bigint                                                        DEFAULT NULL COMMENT '瀛愯瘯鍗穒d',
    PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=131 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC;
