-- Table structure for table `t_exam_paper_child`
--

DROP TABLE IF EXISTS `t_exam_paper_child`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_exam_paper_child`
(
    `id`                     bigint NOT NULL AUTO_INCREMENT,
    `name`                   varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '璇曞嵎鍚嶇О',
    `paper_type`             int                                                           DEFAULT NULL COMMENT '璇曞嵎绫诲瀷(浜哄伐缁勫嵎銆佹娊棰樼粍鍗枫€侀殢鏈虹粍鍗?',
    `score`                  int                                                           DEFAULT NULL COMMENT '璇曞嵎鍒嗘暟',
    `question_count`         int                                                           DEFAULT NULL COMMENT '棰樼洰鏁伴噺',
    `suggest_time`           int                                                           DEFAULT NULL COMMENT '鑰冭瘯鏃堕暱',
    `limit_start_time`       datetime                                                      DEFAULT NULL COMMENT '鑰冭瘯寮€濮嬫椂闂?,
    `limit_end_time`         datetime                                                      DEFAULT NULL COMMENT '鑰冭瘯缁撴潫鏃堕棿',
    `paper_frame_id`         varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci  DEFAULT NULL COMMENT '璇曞嵎缁撴瀯淇℃伅琛↖d',
    `create_user`            int                                                           DEFAULT NULL COMMENT '鍒涘缓浜?,
    `create_time`            datetime                                                      DEFAULT NULL COMMENT '鍒涘缓鏃堕棿',
    `deleted`                bit(1)                                                        DEFAULT NULL COMMENT '鏄惁鍒犻櫎',
    `question_item_mess`     bit(1)                                                        DEFAULT NULL COMMENT '閫夐」鎵撲贡',
    `question_mess`          bit(1)                                                        DEFAULT NULL COMMENT '棰樼洰鎵撲贡',
    `cheat`                  bit(1)                                                        DEFAULT NULL COMMENT '鏄惁闃蹭綔寮?,
    `exam_paper_archive_id`  int                                                           DEFAULT NULL COMMENT '璇曞嵎鍒嗙被',
    `pass_score`             int                                                           DEFAULT NULL COMMENT '鍚堟牸鍒?,
    `exam_paper_build_id`    bigint                                                        DEFAULT NULL COMMENT '璇曞嵎鏋勫缓Id',
    `credential_template_id` int                                                           DEFAULT NULL COMMENT '璇佷功妯℃澘',
    `capture`                bit(1)                                                        DEFAULT NULL COMMENT '鑰冭瘯鎶撴媿',
    `create_department_id`   int                                                           DEFAULT NULL COMMENT '鑰冭瘯鎶撴媿',
    `watch`                  bit(1)                                                        DEFAULT NULL COMMENT '鏄惁鍏佽鏌ョ湅绛斿嵎',
    `max_cheat_count`        int                                                           DEFAULT NULL COMMENT '鏈€澶т綔寮婃鏁?,
    `face_check`             bit(1)                                                        DEFAULT NULL COMMENT '浜鸿劯璇嗗埆',
    `exam_paper_id`          bigint                                                        DEFAULT NULL COMMENT '鐖惰瘯鍗穒d',
    PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=53 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC;
/*!40101 SET character_set_client = @saved_cs_client */;

