INSERT INTO `t_forum` VALUES (1,'鎻愰珮闃呰鐞嗚В鑳藉姏鐨勫涔犲績寰?,'<p>澶у濂斤紒鎴戞槸涓€鍚嶅ぇ涓夊鐢燂紝鍦ㄦ彁楂橀槄璇荤悊瑙ｈ兘鍔涙柟闈紝鎴戠Н绱簡涓€浜涘涔犲績寰椼€傞鍏堬紝鎴戝彂鐜板璇讳功瀵规彁楂橀槄璇荤悊瑙ｅ緢鏈夊府鍔┿€傞€氳繃骞挎硾闃呰鍚勭被鏂囩珷銆佸皬璇村拰鏂伴椈锛岃兘澶熼敾鐐艰嚜宸辩殑闃呰閫熷害鍜岀悊瑙ｈ兘鍔涖€傚叾娆★紝娉ㄦ剰鎻愬墠棰勪範鍜屽涔犮€傚湪闃呰涔嬪墠锛屽厛娴忚涓€閬嶆枃绔狅紝浜嗚В澶ц嚧鍐呭鍜岀粨鏋勶紝瀵逛簬鐞嗚В鏁翠綋鎰忎箟寰堟湁甯姪銆傛渶鍚庯紝瑕佹敞閲嶇Н绱瘝姹囧拰闃呰鎶€宸с€傞€氳繃鑳屽崟璇嶃€佺Н绱煭璇拰闃呰鎶€宸х殑璁粌锛岃兘澶熸洿濂藉湴鐞嗚В鏂囩珷涓殑璇嶆眹鍜屽彞瀛愮粨鏋勩€傚笇鏈涙垜鐨勭粡楠屽澶у鏈夋墍甯姪锛?br/></p>',2,'2025-10-22 00:38:51',_binary '\0',1,2);
INSERT INTO `t_forum` VALUES (2,'瀛︿範缂栫▼鐨勫績寰椾綋浼?,'<p>澶у濂斤紒鎴戞槸涓€鍚嶈绠楁満绉戝涓撲笟鐨勫鐢燂紝鍦ㄥ涔犵紪绋嬭繃绋嬩腑锛屾垜绉疮浜嗕竴浜涘績寰椾綋浼氾紝鎯充笌澶у鍒嗕韩涓€涓嬨€傞鍏堬紝鍧氭寔鍔ㄦ墜瀹炶返鏄涔犵紪绋嬬殑鍏抽敭銆傚彧鏈夐€氳繃瀹為檯鍘荤紪鍐欎唬鐮併€佽В鍐抽棶棰橈紝鎵嶈兘鐪熸鐞嗚В缂栫▼璇█鍜岀畻娉曘€傚叾娆★紝鍩瑰吇鑹ソ鐨勯€昏緫鎬濈淮鑳藉姏闈炲父閲嶈銆傜紪绋嬫秹鍙婂埌璁稿閫昏緫鍜岀畻娉曪紝鍥犳瑕佸煿鍏婚€昏緫鎬濈淮涔犳儻锛岃兘澶熷揩閫熷垎鏋愬拰瑙ｅ喅闂銆傚彟澶栵紝澶氬弬鍔犵紪绋嬮」鐩拰鍥㈤槦鍚堜綔锛岃兘澶熼敾鐐艰嚜宸辩殑瀹炶返鑳藉姏鍜屽洟闃熷崗浣滆兘鍔涖€傚笇鏈涙垜鐨勭粡楠屽澶у鏈夋墍鍚彂锛?br/></p>',2,'2026-02-10 14:58:06',_binary '\0',1,2);
