INSERT INTO `t_forum` VALUES (4,'鑰冭瘯缁忛獙蹇冨緱','<p>澶у濂斤紝鎴戞槸涓€鍚嶅ぇ浜屽鐢燂紝闈㈠姣忔鑰冭瘯锛屾垜閮戒細鎶婇敊璇殑棰樿繘琛屾暣鐞嗭紝瀵逛簬澶氭鍑洪敊鐨勯鍨嬶紝鎴戜細閲嶇偣鏍囪锛屽苟鍔犱互澶氭缁冧範锛屾潵闄嶄綆鍑洪敊鐜囷紝鎶婂娆″嚭鐜扮殑鐭ヨ瘑鐐癸紝杩涜鎬荤粨锛岄亣鍒颁笉浼氱殑棰橈紝浼氱Н鏋佸悜鑰佸笀銆佸悓瀛﹁鏁欍€傚笇鏈涙垜鐨勭粡楠屼細瀵瑰ぇ瀹舵湁鎵€甯姪!</p>',5,'2026-01-08 15:11:48',_binary '\0',2,6);
INSERT INTO `t_forum` VALUES (5,'**','<p>澶у濂斤紝鎴戞槸涓€鍚嶅ぇ浜屽鐢燂紝闈㈠姣忔鑰冭瘯锛屾垜閮戒細鎶婇敊璇?棰樿繘琛屾暣鐞嗭紝瀵逛簬澶氭鍑洪敊*棰樺瀷锛屾垜浼氶噸鐐规爣璁帮紝骞跺姞浠ュ娆＄粌涔狅紝鏉ラ檷浣庡嚭閿欑巼锛屾妸澶氭鍑虹幇*鐭ヨ瘑鐐癸紝杩涜鎬荤粨锛岄亣鍒颁笉浼?棰橈紝浼氱Н鏋佸悜鑰佸笀銆佸悓瀛﹁鏁欍€傚笇鏈涙垜*缁忛獙浼氬澶у鏈夋墍甯姪!</p>',4,'2026-01-03 22:04:43',_binary '',4,7);
