CREATE TABLE `t_menu`
(
    `id`                   int NOT NULL AUTO_INCREMENT,
    `menu_name`            varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '鑿滃崟鍚嶇О',
    `path`                 varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '椤甸潰璺緞',
    `meta_title`           varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '鑿滃崟鍚嶇О',
    `meta_icon`            varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '鑿滃崟鍥炬爣',
    `meta_no_cache`        bit(1)                                                        DEFAULT NULL COMMENT '鏄惁缂撳瓨',
    `meta_affix`           bit(1)                                                        DEFAULT NULL,
    `meta_active_menu`     varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '婵€娲昏彍鍗?,
    `hidden`               bit(1)                                                        DEFAULT NULL COMMENT '鏄惁闅愯棌',
    `component`            varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '瑙嗗浘璺緞',
    `parent_id`            int                                                           DEFAULT NULL COMMENT '鐖剁骇Id',
    `deleted`              bit(1)                                                        DEFAULT NULL COMMENT '鏄惁鍒犻櫎',
    `create_user`          int                                                           DEFAULT NULL COMMENT '鍒涘缓浜?,
    `create_time`          datetime                                                      DEFAULT NULL COMMENT '鍒涘缓鏃堕棿',
    `level`                int                                                           DEFAULT NULL COMMENT '鑿滃崟灞傜骇',
    `always_show`          bit(1)                                                        DEFAULT NULL COMMENT '鏄惁甯告樉',
    `item_order`           int                                                           DEFAULT NULL COMMENT '鎺掑簭',
    `name`                 varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '鑿滃崟鍚嶇О',
    `create_department_id` int                                                           DEFAULT NULL,
    PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=79 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;
