    `item_order`           int                                                           DEFAULT NULL COMMENT '鎺掑簭',
    `create_user_id`       int                                                           DEFAULT NULL,
    `create_department_id` int                                                           DEFAULT NULL,
    PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=207 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;
