--
-- Table structure for table `t_practice_build`
--

DROP TABLE IF EXISTS `t_practice_build`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_practice_build`
(
    `id`                     bigint NOT NULL AUTO_INCREMENT,
    `exam_paper_archive_id`  int                                                           DEFAULT NULL COMMENT '璇曞嵎鍒嗙被Id',
    `name`                   varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '璇曞嵎鍚嶇О',
    `build_type`             int                                                           DEFAULT NULL COMMENT '1.浜哄伐缁勫嵎 2.鎶介缁勫嵎 3.闅忔満缁勫嵎',
    `pass_score`             int                                                           DEFAULT NULL COMMENT '鑰冭瘯鍚堟牸鍒嗘暟',
    `score`                  int                                                           DEFAULT NULL COMMENT '璇曞嵎鎬诲垎',
    `question_count`         int                                                           DEFAULT NULL COMMENT '棰樼洰鎬绘暟',
    `suggest_time`           int                                                           DEFAULT NULL COMMENT '璇曞嵎鏃堕暱',
    `limit_start_time`       datetime                                                      DEFAULT NULL COMMENT '鑰冭瘯寮€濮嬫椂闂?,
    `limit_end_time`         datetime                                                      DEFAULT NULL COMMENT '鑰冭瘯缁撴潫鏃堕棿',
    `create_user`            int                                                           DEFAULT NULL COMMENT '鍒涘缓浜?,
    `create_time`            datetime                                                      DEFAULT NULL COMMENT '鍒涘缓鏃堕棿',
    `deleted`                bit(1)                                                        DEFAULT NULL COMMENT '鏄惁鍒犻櫎',
    `practice_exam_paper_id` bigint                                                        DEFAULT NULL COMMENT '璇曞嵎Id',
    `build_config`           json                                                          DEFAULT NULL COMMENT '鏋勫缓璇曞嵎閰嶇疆',
    `create_department_id`   int                                                           DEFAULT NULL COMMENT '鍒涘缓浜洪儴闂?,
    PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;
/*!40101 SET character_set_client = @saved_cs_client */;

