    `score`                int                                                          DEFAULT NULL COMMENT '鍒嗘暟',
    `difficult`            int                                                          DEFAULT NULL COMMENT '闅惧害',
    `question_frame_id`    varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '棰樼洰鍐呭Id',
    `create_user`          int                                                          DEFAULT NULL COMMENT '鍒涘缓浜?,
    `status`               int                                                          DEFAULT NULL COMMENT '棰樼洰鐘舵€?,
    `create_time`          datetime                                                     DEFAULT NULL COMMENT '鍒涘缓鏃堕棿',
    `deleted`              bit(1)                                                       DEFAULT NULL COMMENT '鏄惁鍒犻櫎',
    `create_department_id` int                                                          DEFAULT NULL,
    PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=332 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;
